import{_ as d,o as r,c as a,a2 as o}from"./chunks/framework.wVcpyw2-.js";const c=JSON.parse('{"title":"社区内容组件","description":"社区内容组件：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/ui-editor/components-community.md","filePath":"features/ui-editor/components-community.md","lastUpdated":1785051348000}'),e={name:"features/ui-editor/components-community.md"};function n(s,t,i,l,h,g){return r(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="社区内容组件" tabindex="-1">社区内容组件 <a class="header-anchor" href="#社区内容组件" aria-label="Permalink to &quot;社区内容组件&quot;">​</a></h1><p>左侧组件库 <strong>「社区内容」</strong> 分类共 8 个组件，用于首页、发现页等场景的 <strong>话题、圈子、笔记</strong> 展示。在 <strong>UI管理 → 页面配置</strong> 中拖入画布，右侧 <strong>属性</strong> Tab 调内容与开关，<strong>样式</strong> Tab 调间距与背景。</p><hr><h2 id="使用前须知" tabindex="-1">使用前须知 <a class="header-anchor" href="#使用前须知" aria-label="Permalink to &quot;使用前须知&quot;">​</a></h2><h3 id="数据来源" tabindex="-1">数据来源 <a class="header-anchor" href="#数据来源" aria-label="Permalink to &quot;数据来源&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组件</th><th>线上数据来源</th><th>编辑器内</th></tr></thead><tbody><tr><td>话题气泡、热门圈子、热门话题、我的圈子</td><td>发现页接口自动拉取</td><td>演示数据，仅预览布局</td></tr><tr><td>笔记列表、圈子列表、瀑布流</td><td>分页接口，支持下拉加载</td><td>可塞示例笔记预览样式</td></tr><tr><td>讨论短卡</td><td><strong>您在属性里配置的卡片</strong></td><td>与线上一致</td></tr></tbody></table><p>改样式后须 <strong>保存 → 启用</strong> 页面，客户端才会生效。</p><h3 id="列表类组件互斥-重要" tabindex="-1">列表类组件互斥（重要） <a class="header-anchor" href="#列表类组件互斥-重要" aria-label="Permalink to &quot;列表类组件互斥（重要）&quot;">​</a></h3><p><strong>圈子列表</strong>、<strong>笔记列表</strong>、<strong>笔记瀑布流</strong> 三者 <strong>同一页面只能保留一种</strong>，且建议放在画布 <strong>最靠下</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>轮播 / 金刚区 / 筛选标签</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>话题气泡、榜单、讨论短卡 等运营模块</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>圈子列表 或 笔记列表 或 瀑布流（三选一）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>结束文本（homeListFooter，可选）</span></span></code></pre></div><p>若同时添加两种，编辑器会 <strong>保留先出现的一种</strong>，自动移除另一种。</p><h3 id="样式分层-列表-瀑布流-圈子列表" tabindex="-1">样式分层（列表 / 瀑布流 / 圈子列表） <a class="header-anchor" href="#样式分层-列表-瀑布流-圈子列表" aria-label="Permalink to &quot;样式分层（列表 / 瀑布流 / 圈子列表）&quot;">​</a></h3><p>这三类组件结构特殊，请区分 <strong>外层</strong> 与 <strong>卡片内</strong>（详见 <a href="/features/ui-editor/styles-and-actions#列表-section-的样式分层">样式与点击动作 · 列表 Section 的样式分层</a>）：</p><table tabindex="0"><thead><tr><th>配置位置</th><th>作用对象</th></tr></thead><tbody><tr><td><strong>样式 Tab → 尺寸、外边距</strong></td><td>整个列表区域外壳</td></tr><tr><td><strong>样式 Tab → 内边距、背景、圆角、边框</strong></td><td>每一条 <strong>卡片</strong> 的外壳</td></tr><tr><td><strong>属性 Tab 里的字号、颜色、开关等</strong></td><td>卡片内部具体元素</td></tr></tbody></table><p>圈子列表的卡片样式保存在 <strong>templateCardProps</strong>（模板卡片属性）中，与笔记列表、瀑布流同理：属性管「卡片长什么样」，样式 Tab 管「区域和卡片盒模型」。</p><hr><h2 id="话题气泡-xiaoyi-topic-bubbles" tabindex="-1">话题气泡（xiaoyi-topic-bubbles） <a class="header-anchor" href="#话题气泡-xiaoyi-topic-bubbles" aria-label="Permalink to &quot;话题气泡（xiaoyi-topic-bubbles）&quot;">​</a></h2><h3 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>双行 <strong>横向滚动</strong> 的热门话题胶囊，带模块标题与「查看更多」。运行时拉取发现页 <strong>热门话题</strong>；标记为最热的话题显示 <strong>最热</strong> 标签，部分话题可显示 <strong>新奇</strong> 标签。点击气泡进入话题详情，「查看更多」默认进入热门话题榜。</p><h3 id="适用页面" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><p>应用首页、发现页（放在列表区块 <strong>上方</strong>）。</p><h3 id="属性配置" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th><th>说明</th></tr></thead><tbody><tr><td>标题栏</td><td>标题、标题字号/颜色</td><td>模块主标题，如「热门话题」</td></tr><tr><td></td><td>HOT 角标、角标文字</td><td>标题旁小角标，可隐藏</td></tr><tr><td>左侧图标</td><td>图片 URL / 图标名</td><td>标题左侧装饰；有图优先于图标</td></tr><tr><td></td><td>图标背景/颜色、边长</td><td>图标容器样式</td></tr><tr><td>查看更多</td><td>显示/隐藏、文案、颜色/字号</td><td>右侧「查看更多 ›」</td></tr><tr><td></td><td>箭头图标、点击动作</td><td>未设置则进热门话题榜</td></tr><tr><td>滚动</td><td>自动滚动、单圈时长</td><td>两行气泡是否自动横向滚动</td></tr><tr><td></td><td>第二行反向</td><td>第二行滚动方向是否与第一行相反</td></tr><tr><td>气泡样式</td><td>圆角、背景色、话题字号</td><td>统一作用于每个话题胶囊</td></tr><tr><td></td><td>气泡间距、行间距</td><td>横向与纵向间距（rpx）</td></tr><tr><td></td><td>左侧小圆图标、背景/图标色</td><td>气泡内 # 或图标</td></tr><tr><td></td><td>项点击动作</td><td>未设置则进话题详情</td></tr><tr><td>标签样式</td><td>新奇/最热 文案、背景/文字色</td><td>话题上的强调标签</td></tr></tbody></table><h3 id="样式说明" tabindex="-1">样式说明 <a class="header-anchor" href="#样式说明" aria-label="Permalink to &quot;样式说明&quot;">​</a></h3><p>模块整体宽高、外边距、背景在 <strong>样式</strong> Tab 配置。气泡颜色多在 <strong>属性 → 气泡统一样式</strong> 中设置，便于与品牌色统一。</p><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>话题 <strong>名单与排序</strong> 由平台算法下发，不能在编辑器里逐条增删。</li><li>关闭自动滚动后，用户仍可手动横滑浏览。</li><li>编辑器内为演示数据， <strong>HOT / 新奇</strong> 标签样式可在此调好，上线后由真实话题数据驱动显示。</li></ul><hr><h2 id="圈子列表-xiaoyi-circle-list-section" tabindex="-1">圈子列表（xiaoyi-circle-list-section） <a class="header-anchor" href="#圈子列表-xiaoyi-circle-list-section" aria-label="Permalink to &quot;圈子列表（xiaoyi-circle-list-section）&quot;">​</a></h2><h3 id="说明-1" tabindex="-1">说明 <a class="header-anchor" href="#说明-1" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>首页 <strong>圈子 Feed 列表</strong>：每条展示圈子 logo、名称、简介、成员/帖子/人气统计、加入按钮、精选笔记等。数据 <strong>分页加载</strong>，可与上方 <strong>筛选标签</strong> 联动排序。</p><p>卡片外观配置保存在 <strong>templateCardProps</strong>（与属性面板中各项对应），列表区域外壳在 <strong>样式</strong> Tab 编辑。</p><h3 id="适用页面-1" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面-1" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><p>应用首页、发现页（画布 <strong>底部</strong>，与笔记列表/瀑布流 <strong>互斥</strong>）。</p><h3 id="属性配置-1" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置-1" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th><th>说明</th></tr></thead><tbody><tr><td>筛选联动</td><td>联动标识 filterLinkKey</td><td>与「筛选标签」相同则受 Tab 控制；默认 <code>default</code></td></tr><tr><td>信息展示</td><td>显示副标题、角标、置顶角标</td><td>控制描述文字与标签显隐</td></tr><tr><td></td><td>对齐方式</td><td>统计信息与标题对齐，或列表左对齐</td></tr><tr><td></td><td>演示分类名</td><td><strong>仅编辑器预览</strong> 角标分类用</td></tr><tr><td>统计</td><td>成员/帖子/人气 显示开关</td><td>可单独隐藏某项</td></tr><tr><td></td><td>成员胶囊样式</td><td>成员数以胶囊或行内形式展示</td></tr><tr><td></td><td>各统计文案、字号/颜色/字重</td><td>如「成员」「帖子」「人气」</td></tr><tr><td>加入按钮</td><td>显示开关、文案、背景/字色/字号</td><td>未加入时「+ 加入」等</td></tr><tr><td></td><td>宽/高/圆角/内边距</td><td>按钮尺寸</td></tr><tr><td></td><td>需审核时文案</td><td>如「申请加入」</td></tr><tr><td>已加入 / 审核中</td><td>各状态文案与颜色</td><td>已加入、审核中按钮样式</td></tr><tr><td>精选区</td><td>显示精选条、更多 ⋮</td><td>圈子下精选笔记预览</td></tr><tr><td></td><td>精选模板</td><td><strong>单行</strong> 或 <strong>卡片</strong> 两种样式</td></tr><tr><td></td><td>精选卡片样式</td><td>选「卡片」模板时的背景、头像、内容等</td></tr><tr><td>图标</td><td>更多/精选 图标名、字号、颜色</td><td>一般保持默认即可</td></tr><tr><td>卡片样式</td><td>内边距、圆角、logo 尺寸</td><td>单条圈子卡片外观</td></tr><tr><td></td><td>标题/副标题字号、角标/药丸颜色</td><td>文字与标签样式</td></tr><tr><td>点击</td><td>卡片/精选区/加入按钮 点击动作</td><td>未设置时使用系统默认跳转</td></tr></tbody></table><h3 id="样式说明-1" tabindex="-1">样式说明 <a class="header-anchor" href="#样式说明-1" aria-label="Permalink to &quot;样式说明&quot;">​</a></h3><p>遵循上文 <strong>样式分层</strong>：<strong>外边距</strong> 调列表与上方模块的距离；<strong>卡片背景、圆角、内边距</strong> 在样式 Tab 或属性中的卡片样式组配置，避免把卡片背景误设到最外层。</p><h3 id="注意事项-1" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项-1" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>与 <strong>笔记列表、瀑布流互斥</strong>，一页只能有一种主 Feed。</li><li><strong>filterLinkKey</strong> 须与筛选标签组件一致，否则切换 Tab 不会刷新圈子列表。</li><li><strong>演示分类名</strong> 不影响线上；线上角标来自圈子真实分类。</li><li>加入按钮行为（直接加入 / 需审核）由圈子设置决定，此处只改 <strong>按钮文案与颜色</strong>。</li></ul><hr><h2 id="笔记列表-xiaoyi-note-list-section" tabindex="-1">笔记列表（xiaoyi-note-list-section） <a class="header-anchor" href="#笔记列表-xiaoyi-note-list-section" aria-label="Permalink to &quot;笔记列表（xiaoyi-note-list-section）&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">完整手册</p><p>本篇为概要。属性面板 <strong>15 个分组、全部字段、三套配置方案、联动与验收</strong> 请参阅：</p><p>👉 <strong><a href="/features/ui-editor/components/note-list">笔记列表组件（完整手册）</a></strong></p></div><h3 id="说明-2" tabindex="-1">说明 <a class="header-anchor" href="#说明-2" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>首页 <strong>笔记 Feed 列表</strong>（双列/多行卡片流），展示用户发布的图文、视频、音频笔记。列表数据来自接口；属性面板主要控制 <strong>卡片模板、显示项、样式</strong>，不修改笔记正文内容。</p><h3 id="适用页面-2" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面-2" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><p>应用首页、发现页（画布 <strong>底部</strong>，与圈子列表/瀑布流 <strong>互斥</strong>）。</p><hr><h3 id="模板选择" tabindex="-1">模板选择 <a class="header-anchor" href="#模板选择" aria-label="Permalink to &quot;模板选择&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>选项</th><th>说明</th></tr></thead><tbody><tr><td>uiTemplate（底栏样式）</td><td><strong>1 传统双行</strong></td><td>底部一行点赞、评论、浏览等互动数据</td></tr><tr><td></td><td><strong>2 评论条</strong></td><td>底部为装饰性「写评论…」输入条（不能真发评论）</td></tr><tr><td></td><td><strong>3 简洁一行</strong></td><td>互动区更紧凑，默认推荐</td></tr><tr><td>contentLayout（正文区域宽度）</td><td><strong>跟随底栏</strong></td><td>正文与底栏同宽</td></tr><tr><td></td><td><strong>与头像对齐</strong></td><td>正文左缘与头像右缘对齐</td></tr><tr><td></td><td><strong>撑满整行</strong></td><td>正文占满卡片宽度</td></tr><tr><td>thumbSize</td><td>封面边长（rpx）</td><td>列表右侧小缩略图尺寸，默认约 176</td></tr></tbody></table><p><strong>视频笔记详情页</strong>（需相应模块授权）：</p><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td>平台详情页</td><td>进入标准笔记详情</td></tr><tr><td>视频播放页</td><td>纯视频笔记进入沉浸式播放页</td></tr></tbody></table><hr><h3 id="显示开关" tabindex="-1">显示开关 <a class="header-anchor" href="#显示开关" aria-label="Permalink to &quot;显示开关&quot;">​</a></h3><p>点属性里 <strong>显示哪些内容</strong> 区域的 pill 可快速开关（关闭后对应区域不显示，接口数据仍保留）：</p><table tabindex="0"><thead><tr><th>分组</th><th>开关</th><th>说明</th></tr></thead><tbody><tr><td>媒体</td><td>图片视频 showCover</td><td>封面图、多图、视频、音频区域</td></tr><tr><td></td><td>多图横滑 multiImageScroll</td><td>多图时横向滑动展示</td></tr><tr><td></td><td>拼图样式 imageCollageTemplate</td><td>多图拼图布局</td></tr><tr><td>正文与话题</td><td>话题标签 hideTopic</td><td>关闭即隐藏话题</td></tr><tr><td></td><td>正文摘要 hideContent</td><td>关闭即隐藏正文预览</td></tr><tr><td></td><td>热评预览 hideHotComment</td><td>热门评论一条预览</td></tr><tr><td>作者</td><td>昵称下行 authorSublineTimeCircle</td><td>「日期 | 来自 · 圈子名」一行</td></tr><tr><td></td><td>认证标签 hideAuthorMetaRow</td><td>性别、认证等用户标签</td></tr><tr><td></td><td>位置圈子 hideLocationCircleRow</td><td>正文下方位置/圈子行</td></tr><tr><td>底栏</td><td>底栏时间 hideFooterTime</td><td>底部时间文字</td></tr></tbody></table><p><strong>预览示例</strong>（仅编辑器）：可切换单图 / 多图 / 视频 / 音频示例，方便查看不同模板效果， <strong>不影响线上数据</strong>。</p><hr><h3 id="筛选联动" tabindex="-1">筛选联动 <a class="header-anchor" href="#筛选联动" aria-label="Permalink to &quot;筛选联动&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>filterLinkKey</td><td>与首页 <strong>筛选标签（笔记）</strong> 使用相同标识时，切换 Tab 会刷新本列表；默认填 <code>default</code></td></tr></tbody></table><p>筛选标签侧须将 <strong>联动目标</strong> 设为笔记，且各 Tab 项配置好 <code>note_order_by</code> 等排序参数。</p><hr><h3 id="样式分层" tabindex="-1">样式分层 <a class="header-anchor" href="#样式分层" aria-label="Permalink to &quot;样式分层&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>配置入口</th><th>典型项</th></tr></thead><tbody><tr><td>列表外壳</td><td><strong>样式 Tab</strong> → 尺寸、外边距</td><td>列表与上方模块间距</td></tr><tr><td>卡片外壳</td><td><strong>样式 Tab</strong> → 内边距、背景、圆角、边框</td><td>单条笔记卡片背景</td></tr><tr><td>卡片内容</td><td><strong>属性 Tab</strong> 各分组</td><td>见下表</td></tr></tbody></table><p><strong>属性 Tab 主要样式分组</strong></p><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th></tr></thead><tbody><tr><td>作者区</td><td>头像大小/圆角、昵称字号/颜色/字重</td></tr><tr><td>昵称下行</td><td>字号/颜色/间距、圈子头像与名称、箭头、胶囊内边距（开启昵称下行时）</td></tr><tr><td>标题与正文</td><td>标题/正文字号、颜色、字重、行高；次要文字颜色 mutedColor</td></tr><tr><td>底栏互动</td><td>赞/评/浏览 文案、图标颜色、已赞色、数字字号</td></tr><tr><td>评论条（模板 2）</td><td>占位提示、输入框背景/圆角、小头像、前置图标或 emoji</td></tr><tr><td>位置与圈子行</td><td>圈子图标大小/圆角（正文下方一行）</td></tr><tr><td>音频笔记</td><td>播放按钮文案、标题字号/颜色</td></tr><tr><td>图标（高级）</td><td>评论/赞/分享 自定义图标名，一般保持默认</td></tr></tbody></table><p><strong>用户标签</strong>（性别、认证、热门等）样式由 <strong>UI管理 → 自定义标签</strong> 统一配置，不在此组件逐条设置。</p><h3 id="注意事项-2" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项-2" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>与 <strong>圈子列表、瀑布流互斥</strong>；请放在页面偏下并配合 <strong>结束文本（homeListFooter）</strong> 作页脚。</li><li><strong>uiTemplate</strong> 切换后，部分显示开关的默认组合会变，切换模板后建议再检查一遍开关。</li><li><strong>预览作者信息</strong> 仅装修预览，线上以接口返回为准。</li><li>模板 2 的 <strong>评论条</strong> 仅为视觉引导，点击行为由客户端跳转详情评论。</li></ul><hr><h2 id="笔记瀑布流-xiaoyi-waterfall-section" tabindex="-1">笔记瀑布流（xiaoyi-waterfall-section） <a class="header-anchor" href="#笔记瀑布流-xiaoyi-waterfall-section" aria-label="Permalink to &quot;笔记瀑布流（xiaoyi-waterfall-section）&quot;">​</a></h2><h3 id="说明-3" tabindex="-1">说明 <a class="header-anchor" href="#说明-3" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p><strong>双列错落</strong> 的笔记瀑布流，适合图片社区、种草类首页。无图纯文笔记会以固定高度文字卡片展示；带图笔记按图片比例计算高度。</p><h3 id="适用页面-3" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面-3" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><p>应用首页、发现页（画布 <strong>底部</strong>，与圈子/笔记列表 <strong>互斥</strong>）。</p><h3 id="属性配置-2" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置-2" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th><th>说明</th></tr></thead><tbody><tr><td>筛选联动</td><td>filterLinkKey</td><td>同笔记列表，与筛选标签联动</td></tr><tr><td>视频详情</td><td>平台详情页 / 视频播放页</td><td>同笔记列表</td></tr><tr><td>布局</td><td>列间距 columnGap、卡片间距 cardGap</td><td>双列之间的空隙（rpx）</td></tr><tr><td>封面/媒体</td><td>媒体圆角、占位背景</td><td>图片/视频区域</td></tr><tr><td></td><td>竖图最大高度、横图最小高度</td><td>控制错落幅度</td></tr><tr><td></td><td>显示置顶</td><td>置顶笔记角标</td></tr><tr><td>文案</td><td>字号/颜色/字重/行高</td><td>卡片标题或摘要文字</td></tr><tr><td>话题标签</td><td>显示/隐藏、媒体毛玻璃</td><td>左下角话题胶囊</td></tr><tr><td></td><td>字号/颜色/圆角/位置</td><td>话题标签样式</td></tr><tr><td></td><td>纯文/媒体/视频 背景与边框色</td><td>不同笔记类型下标签底色</td></tr><tr><td>纯文卡片</td><td>内容区高度、背景、字号/颜色/行高</td><td>仅无媒体笔记</td></tr><tr><td></td><td>行间下划线类型</td><td>无/实线/虚线/点线/分段</td></tr><tr><td>底栏</td><td>头像/昵称/点赞 字号颜色</td><td>卡片底部作者与赞</td></tr><tr><td></td><td>底栏高度、隐藏点赞</td><td></td></tr><tr><td>音频</td><td>去播放文案</td><td>音频笔记按钮文字</td></tr><tr><td>图标</td><td>多图/视频/音频角标、赞图标</td><td>高级自定义，一般默认即可</td></tr></tbody></table><p><strong>内容模板演示</strong>（仅编辑器）：纯文 / 竖图 / 音频示例，预览双列效果。</p><h3 id="样式说明-2" tabindex="-1">样式说明 <a class="header-anchor" href="#样式说明-2" aria-label="Permalink to &quot;样式说明&quot;">​</a></h3><p>同样遵循 <strong>样式分层</strong>：样式 Tab 管列表区域与卡片盒模型；属性 Tab 管封面圆角、话题胶囊、底栏文字等 <strong>卡片内部</strong> 元素。</p><h3 id="注意事项-3" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项-3" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>与圈子列表、笔记列表 <strong>三选一</strong>。</li><li>纯文卡片高度由 <strong>textOnlyHigh</strong> 等控制，过高会留白，过低会截断文字。</li><li>话题 <strong>毛玻璃</strong> 仅在有封面媒体时效果明显。</li></ul><hr><h2 id="讨论短卡-xiaoyi-talk-cards" tabindex="-1">讨论短卡（xiaoyi-talk-cards） <a class="header-anchor" href="#讨论短卡-xiaoyi-talk-cards" aria-label="Permalink to &quot;讨论短卡（xiaoyi-talk-cards）&quot;">​</a></h2><h3 id="说明-4" tabindex="-1">说明 <a class="header-anchor" href="#说明-4" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p><strong>手动配置</strong> 的短话题/讨论入口卡，支持 <strong>网格</strong> 或 <strong>横滑</strong> 布局。每张卡片含标题、副文案（如讨论数）、可选角标与图标，适合运营位、频道入口、活动聚合。</p><h3 id="适用页面-4" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面-4" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><p>应用首页、发现页、自定义页面（放在列表区块 <strong>上方</strong>）。</p><h3 id="属性配置-3" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置-3" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><p><strong>卡片列表（可多条）</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>标题</td><td>主文案</td></tr><tr><td>副文案</td><td>如 <code>1563讨论</code></td></tr><tr><td>角标</td><td>可选，如「热」</td></tr><tr><td>图标名 / 图标图</td><td>需开启「图标」后生效</td></tr><tr><td>点击动作</td><td>点击整张卡片</td></tr></tbody></table><p><strong>布局</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>布局模式</td><td><strong>网格</strong> 或 <strong>横滑</strong></td></tr><tr><td>列数</td><td>网格时 1 / 2 / 3 列</td></tr><tr><td>卡片宽</td><td>横滑时每张卡片宽度（rpx）</td></tr><tr><td>间距 itemGap</td><td>卡片之间距离</td></tr></tbody></table><p><strong>卡片样式</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>背景色/背景图、边框、圆角</td><td>卡片外观</td></tr><tr><td>内边距、最小高度、阴影</td><td></td></tr></tbody></table><p><strong>标题 / 副文案</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>颜色、字号、字重、对齐、行数</td><td>标题</td></tr><tr><td>副文案颜色、字号、与标题间距</td><td></td></tr></tbody></table><p><strong>增强</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>角标</td><td>显示角标及角标底色/字色</td></tr><tr><td>图标</td><td>显示 lead 图标；位置 <strong>上方</strong> 或 <strong>标题前</strong></td></tr><tr><td>右下箭头</td><td>可选箭头图标及颜色</td></tr></tbody></table><h3 id="样式说明-3" tabindex="-1">样式说明 <a class="header-anchor" href="#样式说明-3" aria-label="Permalink to &quot;样式说明&quot;">​</a></h3><p>组件外层 margin、背景在 <strong>样式</strong> Tab；卡片视觉主要在 <strong>属性 → 卡片样式</strong> 完成。</p><h3 id="注意事项-4" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项-4" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>内容 <strong>不会自动更新</strong>，活动结束请及时改文案或下架卡片。</li><li>横滑模式注意 <strong>卡片宽 + 间距</strong>，避免单屏只露出过窄一条。</li><li>图标图与图标名同时填时，展示优先级以客户端为准，建议 <strong>二选一</strong>。</li></ul><hr><h2 id="我的圈子-xiaoyi-joined-circles" tabindex="-1">我的圈子（xiaoyi-joined-circles） <a class="header-anchor" href="#我的圈子-xiaoyi-joined-circles" aria-label="Permalink to &quot;我的圈子（xiaoyi-joined-circles）&quot;">​</a></h2><h3 id="说明-5" tabindex="-1">说明 <a class="header-anchor" href="#说明-5" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>展示当前用户 <strong>已加入的圈子</strong>，末尾可带 <strong>创建圈子</strong> 入口。运行时拉取「我的圈子」接口；未登录时可能为空或隐藏。</p><h3 id="适用页面-5" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面-5" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><p>应用首页、发现页（通常放在中上部）。</p><h3 id="属性配置-4" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置-4" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th><th>说明</th></tr></thead><tbody><tr><td>模板</td><td>布局模板</td><td><strong>圆头像横滑</strong> 或 <strong>双列信息格</strong></td></tr><tr><td></td><td>列数 / 行间距</td><td>信息格模式下 2 或 3 列</td></tr><tr><td></td><td>项间距、头像尺寸、头像底色</td><td></td></tr><tr><td></td><td>图文间距</td><td>头像与名称距离</td></tr><tr><td>圈子文字</td><td>标题字号/颜色/字重</td><td>圈子名称</td></tr><tr><td></td><td>副标题、成员数后缀</td><td>信息格模式，如「人已加入」</td></tr><tr><td></td><td>占位图标</td><td>无 logo 时的默认图标</td></tr><tr><td>创建入口</td><td>显示策略</td><td><strong>跟随权限</strong> / <strong>始终</strong> / <strong>隐藏</strong></td></tr><tr><td></td><td>文案、图标名/颜色/字号</td><td>如「去创建」「+ 创建圈子」</td></tr><tr><td></td><td>横滑模式</td><td>创建圆底色、描边、文案颜色</td></tr><tr><td></td><td>信息格模式</td><td>胶囊底色/字色/圆角</td></tr><tr><td></td><td>创建点击动作</td><td>未设置则跳创建申请页</td></tr></tbody></table><h3 id="样式说明-4" tabindex="-1">样式说明 <a class="header-anchor" href="#样式说明-4" aria-label="Permalink to &quot;样式说明&quot;">​</a></h3><p>根容器 <strong>宽高、外边距、背景、圆角</strong> 在 <strong>样式</strong> Tab 编辑（属性面板顶部有提示）。</p><h3 id="注意事项-5" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项-5" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li><strong>跟随权限</strong> 时，无创建圈子权限的用户看不到创建入口。</li><li>编辑器内为演示数据， <strong>圈子数量与名称</strong> 以用户账号为准。</li><li>横滑模板适合圈子较多；信息格适合强调成员数与简介。</li></ul><hr><h2 id="热门圈子-xiaoyi-hot-circles" tabindex="-1">热门圈子（xiaoyi-hot-circles） <a class="header-anchor" href="#热门圈子-xiaoyi-hot-circles" aria-label="Permalink to &quot;热门圈子（xiaoyi-hot-circles）&quot;">​</a></h2><h3 id="说明-6" tabindex="-1">说明 <a class="header-anchor" href="#说明-6" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>展示平台 <strong>推荐圈子</strong>，运行时拉取发现页 <code>recommended_circles</code>。支持 <strong>横滑卡片</strong> 与 <strong>列表滑动</strong> 两种模板，带加入按钮。</p><h3 id="适用页面-6" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面-6" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><p>应用首页、发现页。</p><h3 id="属性配置-5" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置-5" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th><th>说明</th></tr></thead><tbody><tr><td>模板</td><td>布局模板</td><td><strong>横滑卡片</strong> 或 <strong>列表滑动</strong></td></tr><tr><td></td><td>项间距、成员数后缀</td><td>如「人已加入」</td></tr><tr><td></td><td>头像底色</td><td>无 logo 时占位色</td></tr><tr><td>横滑卡片</td><td>卡片宽/圆角/背景/内边距</td><td>单张推荐卡</td></tr><tr><td></td><td>头像尺寸、名称字号/颜色</td><td></td></tr><tr><td></td><td>底部条背景/字色/高度/对齐</td><td>卡片底部成员数条</td></tr><tr><td>列表滑动</td><td>每列行数、单列宽、行间距</td><td>多列纵向滑动</td></tr><tr><td></td><td>列表背景/圆角/内边距</td><td>列表容器</td></tr><tr><td></td><td>头像尺寸/圆角、名称/副标题样式</td><td>列表行</td></tr><tr><td>加入按钮</td><td>文案、背景/字色、描边</td><td>如「+ 加入」</td></tr><tr><td></td><td>图标名/颜色、点击动作</td><td>未设置则进圈子详情</td></tr></tbody></table><h3 id="样式说明-5" tabindex="-1">样式说明 <a class="header-anchor" href="#样式说明-5" aria-label="Permalink to &quot;样式说明&quot;">​</a></h3><p>模块整体在 <strong>样式</strong> Tab；卡片与列表细节在 <strong>属性</strong> 各模板分组。</p><h3 id="注意事项-6" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项-6" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>推荐名单由 <strong>平台算法</strong> 下发，不能在编辑器里指定具体圈子。</li><li>列表滑动模式下单列宽度不宜超过屏幕宽，否则横滑体验变差。</li><li>加入逻辑（是否需审核）由圈子设置决定，此处只改按钮外观。</li></ul><hr><h2 id="热门话题-xiaoyi-hot-topics" tabindex="-1">热门话题（xiaoyi-hot-topics） <a class="header-anchor" href="#热门话题-xiaoyi-hot-topics" aria-label="Permalink to &quot;热门话题（xiaoyi-hot-topics）&quot;">​</a></h2><h3 id="说明-7" tabindex="-1">说明 <a class="header-anchor" href="#说明-7" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p><strong>完整展示</strong> 发现页热门话题列表（<strong>无横向滑动</strong>，纵向排列）。每条含 # 标识、话题名、笔记数/浏览数等，可选叠头像展示参与用户。</p><h3 id="适用页面-7" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面-7" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><p>应用首页、发现页。</p><h3 id="属性配置-6" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置-6" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th><th>说明</th></tr></thead><tbody><tr><td>模板</td><td>布局模板</td><td><strong>详情行</strong> / <strong>叠头像</strong> / <strong>紧凑行</strong></td></tr><tr><td></td><td>行间距</td><td>话题行之间距离</td></tr><tr><td></td><td>列数、列间距</td><td>紧凑行模式下多列</td></tr><tr><td># 与标题</td><td># 强调色/字色/尺寸/字号</td><td>井号方块样式</td></tr><tr><td></td><td>标题/副文 字号颜色</td><td>话题名与统计文案</td></tr><tr><td></td><td>热标图标/颜色/尺寸</td><td>热门标识</td></tr><tr><td></td><td>笔记后缀、浏览后缀</td><td>如「笔记」「浏览」</td></tr><tr><td>叠头像</td><td>头像尺寸、重叠量、底色</td><td>仅「叠头像」模板</td></tr><tr><td>点击</td><td>项点击动作</td><td>未设置则进话题详情</td></tr></tbody></table><h3 id="样式说明-6" tabindex="-1">样式说明 <a class="header-anchor" href="#样式说明-6" aria-label="Permalink to &quot;样式说明&quot;">​</a></h3><p>外层容器用 <strong>样式</strong> Tab；# 号与文字颜色在属性中微调即可与品牌色一致。</p><h3 id="注意事项-7" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项-7" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>与 <strong>话题气泡</strong> 不同：气泡偏动感横滑，本组件偏 <strong>榜单式完整列表</strong>。</li><li><strong>紧凑行</strong> 适合话题多、屏效高的场景； <strong>详情行</strong> 信息最全。</li><li>热标是否显示取决于话题是否被标记为热门，非每条都有。</li></ul><hr><h2 id="首页组合参考" tabindex="-1">首页组合参考 <a class="header-anchor" href="#首页组合参考" aria-label="Permalink to &quot;首页组合参考&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>搜索栏 + 筛选标签（filterLinkKey = default）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>话题气泡</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>我的圈子 + 热门圈子（可选）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>讨论短卡 / 首页榜单（运营模块，见下篇）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>笔记列表 或 瀑布流 或 圈子列表（三选一）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>结束文本（homeListFooter = true）</span></span></code></pre></div><hr><h2 id="系列导航" tabindex="-1">系列导航 <a class="header-anchor" href="#系列导航" aria-label="Permalink to &quot;系列导航&quot;">​</a></h2><ul><li>上一篇：<a href="/features/ui-editor/components-display">信息展示组件</a></li><li>下一篇：<a href="/features/ui-editor/components-marketing">运营模块组件</a></li></ul>`,145)])])}const p=d(e,[["render",n]]);export{c as __pageData,p as default};
